parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "selected_area": {
      "type": "string",
      "description": "The processing area selected for the user’s request.",
      "enum": [
        "calendar_area",
        "fallback"
      ]
    }
  },
  "required": [
    "selected_area"
  ],
  "additionalProperties": false
}

parameters.text:
=Original user message: {{ $('Telegram Trigger').item.json.message.text }}
Processing area identifier: {{ $json.area_name }}
Purpose of the processing area: {{ $json.area_description }}
Requested action completed (true/false): {{ $json.success }}
Area-specific outcome code: {{ $json.status }}
Outcome details and resulting data: {{ $json.details }}
